```java
// [extrait de code 2]
// Correction : Utilisation sécurisée avec validation et contrôle des sources
// Vérification du chemin du fichier avant de le charger, évite l'exploitation par injection de classes

import java.io.File;
import java.net.URL;

public class SafeDynamicClassLoader {
    private static final String SAFE_CLASS_PATH = "/safe_classes/";

    public static void loadClass(String className) throws Exception {
        // Vérification que le nom de la classe est valide et dans le répertoire autorisé
        if (className == null || !className.contains(".")) {
            throw new IllegalArgumentException("Nom de classe invalide");
        }

        String[] parts = className.split("\\.");
        String fileName = parts[parts.length - 1] + ".class";
        File file = new File(SAFE_CLASS_PATH + fileName);

        if (!file.exists() || !file.isFile()) {
            throw new IllegalArgumentException("Fichier de classe non trouvé ou invalide");
        }

        URL url = file.toURI().toURL();
        Class<?> clazz = Class.forName(className, true, url.openConnection().getURL().getClassLoader());
        Object instance = clazz.getDeclaredConstructor().newInstance();
        System.out.println("Classe chargée en toute sécurité : " + clazz.getName());
    }
}
```

