public class VulnerableAPIUsage {
    // Уязвимый: Непроверенные входные данные могут быть использованы для выполнения произвольного кода
    public void processInput(String input) {
        String result = new String(input.getBytes(), "UTF-8");
        System.out.println(result);
    }
}
***
public class SecureAPIUsage {
    // Хорошо: Проверка и очистка входных данных перед обработкой
    public void processInput(String input) {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Входная строка не может быть пустой.");
        }

        // Очистка от специальных символов, которые могут быть использованы для инъекций
        String sanitizedInput = input.replaceAll("[^a-zA-Z0-9\\s]", "");

        String result = new String(sanitizedInput.getBytes(), "UTF-8");
        System.out.println(result);
    }
}
```

