// Corretto: uso di PreparedStatement per prevenire le iniezioni SQL
// Utilizzo di un pool di connessioni e parametri dinamici

// Configurazione separata in un file esterno o ambiente
String url = "jdbc:mysql://localhost:3306/mydb";
String user = "app_user";
String password = "secure_password";

try (Connection conn = dataSource.getConnection()) { // dataSource è configurato con pooling
    String usernameParam = request.getParameter("username");
    String query = "SELECT * FROM users WHERE username = ?";
    try (PreparedStatement pstmt = conn.prepareStatement(query)) {
        pstmt.setString(1, usernameParam);
        try (ResultSet rs = pstmt.executeQuery()) {
            while (rs.next()) {
                System.out.println(rs.getString("email"));
            }
        }
    }
} catch (SQLException e) {
    log.error("Errore durante l'accesso al database", e);
}
