[frammento di codice 2]  
```java
// Corretto: utilizzo di PreparedStatement per prevenire SQL injection e gestione eccezioni più robusta
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureAPIExample {
    public static void main(String[] args) {
        String url = "jdbc:mysql://localhost:3306/mydb";
        String user = "root";
        String password = "password";

        try (Connection conn = DriverManager.getConnection(url, user, password)) {
            // Input utente filtrato e sanitizzato prima di essere usato
            String userInput = "userInput".replaceAll("[^a-zA-Z0-9_]", ""); // Sanitizzazione semplice

            String sql = "SELECT * FROM users WHERE username = ?";
            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
                pstmt.setString(1, userInput);

                try (ResultSet rs = pstmt.executeQuery()) {
                    while (rs.next()) {
                        System.out.println("Utente trovato: " + rs.getString("username"));
                    }
                }
            }
        } catch (Exception e) {
            // Loggare l'errore con dettagli appropriati in un ambiente reale
            e.printStackTrace();
        }
    }
}
```

